import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import { Bell, CheckCircle2, ChevronRight, Command, Eye, EyeOff, KeyRound, Moon, PanelLeft, RefreshCw, Search, ShieldCheck, Sun, X } from "lucide-react";
import {
  type AgentRecord, type AgentToolMode, type AgentToolRecord, type ApprovalRecord, type ConnectionState, type EventEnvelope, type HealthResponse, type InstallJobRecord, type SessionRecord, type SystemResponse, type TaskRecord,
  UtharnessClient, UtharnessEventStream, getRuntimeConfig,
} from "@utharness/frontend-client";
import { StatusBeacon, ThreeDIcon, type ThreeDIconName, type ThreeDIconState } from "./components/ThreeDIcon.js";
import { AgentBrandIcon } from "./components/AgentBrandIcon.js";

const client = new UtharnessClient(getRuntimeConfig({ apiBaseUrl: import.meta.env.VITE_UTHARNESS_API_URL, websocketUrl: import.meta.env.VITE_UTHARNESS_WS_URL }));
type ModuleName = "overview" | "agents" | "sessions" | "tasks" | "teams" | "workflows" | "memory" | "mcp" | "models" | "permissions" | "terminal" | "audit";
type ThemeName = "dark" | "light";
const navigation: Array<{ id: ModuleName; label: string; icon: ThreeDIconName; detail: string }> = [
  { id: "overview", label: "Overview", icon: "overview", detail: "Mission control" }, { id: "agents", label: "Agents", icon: "agents", detail: "Local registry" },
  { id: "sessions", label: "Sessions", icon: "sessions", detail: "Live runtimes" }, { id: "tasks", label: "Tasks", icon: "tasks", detail: "Shared queue" },
  { id: "teams", label: "Teams", icon: "teams", detail: "Agent council" }, { id: "workflows", label: "Workflows", icon: "workflows", detail: "Execution graphs" },
  { id: "memory", label: "Memory", icon: "memory", detail: "Local context" }, { id: "mcp", label: "MCP", icon: "mcp", detail: "Tool control" },
  { id: "models", label: "Models", icon: "models", detail: "Provider hub" }, { id: "permissions", label: "Permissions", icon: "permissions", detail: "Approval queue" },
  { id: "terminal", label: "Terminal", icon: "terminal", detail: "PTY sessions" }, { id: "audit", label: "Audit", icon: "audit", detail: "Event history" },
];
function formatTime(value: string): string { const date = new Date(value); return Number.isNaN(date.valueOf()) ? "—" : new Intl.DateTimeFormat(undefined, { hour: "2-digit", minute: "2-digit", second: "2-digit" }).format(date); }
function formatDate(value: string | null | undefined): string { if (!value) return "—"; const date = new Date(value); return Number.isNaN(date.valueOf()) ? "—" : date.toLocaleString(); }
function formatUptime(value: number): string { const minutes = Math.max(0, Math.floor(value / 60)); return `${String(Math.floor(minutes / 60)).padStart(2, "0")}h ${String(minutes % 60).padStart(2, "0")}m`; }
function statusClass(status: string): string { return status.toLowerCase().replace(/[^a-z0-9]+/g, "-"); }
function stateFor(status: string): ThreeDIconState { if (["available", "completed", "healthy", "approved", "active"].includes(status)) return "active"; if (["running", "connecting", "pending"].includes(status)) return "running"; if (["failed", "error", "denied"].includes(status)) return "error"; if (["warning", "degraded"].includes(status)) return "warning"; return "neutral"; }
function parseJson<T>(value: string | null | undefined, fallback: T): T { try { return value ? JSON.parse(value) as T : fallback; } catch { return fallback; } }
function normalizeTerminalText(value: string): string { return value.replace(/\u001b\][^\u0007]*(?:\u0007|\u001b\\)/g, "").replace(/[\u001b\u009b][[\]()#;?]*(?:(?:(?:[a-zA-Z\d]*(?:;[-a-zA-Z\d\/#&.:=?%@~_]+)*)?\u0007)|(?:(?:\d{1,4}(?:[;:]\d{0,4})*)?[\dA-PR-TZcf-nq-uy=><~]))/g, "").replace(/\r(?!\n)/g, "\n").replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, ""); }
function setupCommand(tool: AgentToolRecord): string | null { if (tool.installer.kind === "npm" && tool.installer.packageName) return `npm install --global ${tool.installer.packageName}`; if (tool.installer.kind === "python" && tool.installer.packageName) return `python3 -m pip install --user ${tool.installer.packageName}`; return null; }
function useDataLoader<T>(loader: () => Promise<T>, refreshKey: number) { const [data, setData] = useState<T | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null); const reload = useCallback(async () => { setLoading(true); setError(null); try { setData(await loader()); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to load module data"); } finally { setLoading(false); } }, [loader]); useEffect(() => { void reload(); }, [reload, refreshKey]); return { data, loading, error, reload }; }

export default function App() {
  const [activeModule, setActiveModule] = useState<ModuleName>("overview"); const [theme, setTheme] = useState<ThemeName>("dark");
  const [health, setHealth] = useState<HealthResponse | null>(null); const [system, setSystem] = useState<SystemResponse | null>(null); const [agents, setAgents] = useState<AgentRecord[]>([]); const [tasks, setTasks] = useState<TaskRecord[]>([]); const [events, setEvents] = useState<EventEnvelope[]>([]);
  const [connection, setConnection] = useState<ConnectionState>("connecting"); const [loading, setLoading] = useState(true); const [scanning, setScanning] = useState(false); const [paletteOpen, setPaletteOpen] = useState(false); const [paletteQuery, setPaletteQuery] = useState(""); const [credentialsOpen, setCredentialsOpen] = useState(false); const [notice, setNotice] = useState<string | null>(null); const [error, setError] = useState<string | null>(null); const [refreshTick, setRefreshTick] = useState(0);
  const loadDashboard = useCallback(async (): Promise<void> => { setLoading(true); setError(null); try { const [nextHealth, nextSystem, nextAgents, nextTasks, nextEvents] = await Promise.all([client.health(), client.system(), client.agents(), client.tasks(), client.events()]); setHealth(nextHealth); setSystem(nextSystem); setAgents(nextAgents.agents); setTasks(nextTasks.tasks); setEvents(nextEvents.events.map((event) => ({ type: String(event.event_type ?? "event"), payload: parseJson(String(event.payload_json ?? "{}"), {}), at: String(event.created_at) }))); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to reach the backend"); } finally { setLoading(false); } }, []);
  useEffect(() => { void loadDashboard(); }, [loadDashboard]); useEffect(() => { document.documentElement.dataset.theme = theme; }, [theme]);
  useEffect(() => { const stream = new UtharnessEventStream(client.config.websocketUrl); const stopState = stream.onState(setConnection); const stopEvents = stream.onEvent((event) => { setEvents((current) => [event, ...current].slice(0, 40)); setRefreshTick((value) => value + 1); if (event.type.startsWith("agent.") || event.type.startsWith("task.") || event.type.startsWith("system.")) void loadDashboard(); }); stream.connect(); return () => { stopState(); stopEvents(); stream.close(); }; }, [loadDashboard]);
  useEffect(() => { const handleKey = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setPaletteOpen(true); } if (event.key === "Escape") { setPaletteOpen(false); setCredentialsOpen(false); } }; window.addEventListener("keydown", handleKey); return () => window.removeEventListener("keydown", handleKey); }, []);
  const detectedCount = useMemo(() => agents.filter((agent) => agent.status === "available").length, [agents]); const completedTasks = useMemo(() => tasks.filter((task) => task.status === "completed").length, [tasks]); const runningAgents = useMemo(() => agents.filter((agent) => agent.status === "running" || agent.status === "available").length, [agents]); const healthyChecks = health ? Object.values(health.checks).filter((check) => check.healthy).length : 0; const activeNav = navigation.find((item) => item.id === activeModule) ?? navigation[0]!;
  const scanAgents = async (): Promise<void> => { setScanning(true); setError(null); try { const result = await client.detectAgents(); setAgents(result.agents); setNotice(`${result.agents.filter((agent) => agent.detected).length} local agents detected`); } catch (cause) { setError(cause instanceof Error ? cause.message : "Agent scan failed"); } finally { setScanning(false); } };
  const runCommand = (command: string): void => { setPaletteOpen(false); setPaletteQuery(""); if (command === "refresh") void loadDashboard(); else if (command === "scan") void scanAgents(); else if (command === "theme") setTheme((current) => current === "dark" ? "light" : "dark"); else { setActiveModule(command as ModuleName); setNotice(`${navigation.find((item) => item.id === command)?.label ?? "Module"} selected`); } };
  const showError = (cause: unknown): void => setError(cause instanceof Error ? cause.message : "Action failed");
  return <div className="app-shell"><AmbientMesh /><aside className="sidebar glass-surface"><div className="brand"><img className="brand-mark" src="/branding/utharness-mark.svg" alt="" aria-hidden="true" /><div><strong>UTHARNESS OS</strong><span>LOCAL AGENT COMMAND CENTER</span></div></div><div className="system-chip"><StatusBeacon state={connection === "open" ? "active" : connection === "error" ? "error" : "running"} /><span>{connection === "open" ? "EVENT STREAM ONLINE" : connection.toUpperCase()}</span><span className="chip-local">LOCAL</span></div><div className="sidebar-heading"><span>MISSION CONTROL</span><button className="icon-button" aria-label="Collapse sidebar"><PanelLeft size={16} /></button></div><nav>{navigation.map((item) => <button className={`nav-item ${activeModule === item.id ? "active" : ""}`} key={item.id} onClick={() => setActiveModule(item.id)}><ThreeDIcon name={item.icon} size="compact" state={activeModule === item.id ? "active" : "neutral"} /><span><strong>{item.label}</strong><small>{item.detail}</small></span>{item.id === "agents" && <b>{agents.length}</b>}{item.id === "tasks" && <b>{tasks.length}</b>}</button>)}</nav><div className="sidebar-bottom"><div className="workspace-mini"><span className="mini-label">WORKSPACE</span><strong>utharness-os</strong><span className="mono">/home/ubuntu/utharness-os</span></div><button className="workspace-button" onClick={() => setNotice("Workspace path is controlled by the local runtime")}><FolderIcon /> <span>Local workspace</span><ChevronRight size={14} /></button></div></aside><main className="main-content"><header className="topbar"><div className="crumbs"><span className="eyebrow">UTHARNESS / {activeNav.label.toUpperCase()}</span><h1>{activeNav.id === "overview" ? "Mission control" : activeNav.label}</h1></div><div className="top-actions"><button className="search-button pressed-control" onClick={() => setPaletteOpen(true)}><Search size={15} /><span>Search commands</span><kbd>Ctrl K</kbd></button><button className="icon-button pressed-control" aria-label="Notifications" onClick={() => setNotice("No new notifications")}><Bell size={17} /><span className="notification-dot" /></button><button className="icon-button pressed-control" aria-label="Open registry credentials" title="Session-only registry credentials" onClick={() => setCredentialsOpen(true)}><KeyRound size={17} /></button><ThemeToggle theme={theme} onToggle={() => setTheme((current) => current === "dark" ? "light" : "dark")} /></div></header>{error && <div className="error-banner glass-surface"><ThreeDIcon name="permissions" size="compact" state="error" /><span>{error}</span><button onClick={() => void loadDashboard()} className="text-button">Retry</button></div>}{notice && <div className="notice-banner"><CheckCircle2 size={15} /> {notice}<button aria-label="Dismiss notice" onClick={() => setNotice(null)}><X size={14} /></button></div>}{activeModule === "overview" ? <Overview health={health} system={system} agents={agents} tasks={tasks} events={events} connection={connection} detectedCount={detectedCount} runningAgents={runningAgents} completedTasks={completedTasks} healthyChecks={healthyChecks} scanning={scanning} loading={loading} onRefresh={() => void loadDashboard()} onScan={() => void scanAgents()} /> : <ModuleView module={activeModule} agents={agents} tasks={tasks} events={events} refreshKey={refreshTick} onRefresh={() => void loadDashboard()} onNotice={setNotice} onError={showError} onScan={() => void scanAgents()} scanning={scanning} />}<footer className="telemetry-dock glass-surface"><div><span className="telemetry-key">RUNTIME</span><strong>{system ? formatUptime(Math.floor(Date.now() / 1000) - Math.floor(new Date().setHours(0, 0, 0, 0) / 1000)) : "--"}</strong></div><div><span className="telemetry-key">AGENTS</span><strong>{runningAgents.toString().padStart(2, "0")}</strong></div><div><span className="telemetry-key">TASKS</span><strong>{tasks.length.toString().padStart(2, "0")}</strong></div><div><span className="telemetry-key">STREAM</span><strong className={connection === "open" ? "telemetry-good" : "telemetry-warn"}>{connection.toUpperCase()}</strong></div><div className="telemetry-spacer" /><span className="telemetry-path">REST {client.config.apiBaseUrl} · WS {client.config.websocketUrl}</span></footer></main>{paletteOpen && <CommandPalette query={paletteQuery} onQuery={setPaletteQuery} onClose={() => setPaletteOpen(false)} onCommand={runCommand} />}{credentialsOpen && <CredentialDialog onClose={() => setCredentialsOpen(false)} onSaved={(providers) => { setCredentialsOpen(false); setNotice(`${providers.join(" and ")} credential entered for this browser session only`); }} />}</div>;
}

function Overview({ health, system, agents, tasks, events, connection, detectedCount, runningAgents, completedTasks, healthyChecks, scanning, loading, onRefresh, onScan }: { health: HealthResponse | null; system: SystemResponse | null; agents: AgentRecord[]; tasks: TaskRecord[]; events: EventEnvelope[]; connection: ConnectionState; detectedCount: number; runningAgents: number; completedTasks: number; healthyChecks: number; scanning: boolean; loading: boolean; onRefresh: () => void; onScan: () => void }) { return <><section className="hero glass-surface"><div className="hero-copy"><span className="eyebrow accent">LOCAL RUNTIME / 0.1.0</span><h2>See the whole swarm.<br /><em>Move with intent.</em></h2><p>UTHARNESS turns installed AI agents into an observable, permissioned local operating environment.</p><div className="hero-actions"><button className="primary-button pressed-control" onClick={onScan} disabled={scanning}><ThreeDIcon name="agents" size="inline" state="active" />{scanning ? "Scanning environment" : "Scan local agents"}</button><button className="secondary-button pressed-control" onClick={onRefresh} disabled={loading}><RefreshCw size={14} className={loading ? "spin" : ""} /> Refresh telemetry</button></div></div><div className="hero-core"><div className="hero-rings"><span /><span /><span /></div><ThreeDIcon name="system" size="hero" state="running" label="Live local system" /><small>LIVE / LOCAL</small></div></section><section className="metric-grid"><Metric icon="health" label="System health" value={health?.status === "healthy" ? "Healthy" : health ? "Degraded" : "—"} detail={`${healthyChecks}/${health ? Object.keys(health.checks).length : 0} checks`} state={stateFor(health?.status ?? "neutral")} /><Metric icon="agents" label="Agent council" value={String(detectedCount).padStart(2, "0")} detail={`${runningAgents} ready to run`} state="active" /><Metric icon="tasks" label="Task board" value={String(completedTasks).padStart(2, "0")} detail={`${tasks.length} tracked tasks`} state="active" /><Metric icon="database" label="Local authority" value={health?.checks.database?.healthy ? "SQLite" : "—"} detail="Offline-capable store" state="active" /></section><section className="bento-grid"><div className="panel glass-surface agents-panel"><PanelHeader eyebrow="AGENT COUNCIL" title="Local agent registry" icon="agents" action={<button className="text-button" onClick={onScan}>Scan <ChevronRight size={13} /></button>} /><div className="agent-cards">{agents.length === 0 && <EmptyState icon="agents" text={loading ? "Loading registry" : "Scan the local environment to populate the council"} />}{agents.slice(0, 6).map((agent) => <AgentCard key={agent.id} agent={agent} />)}</div></div><div className="panel glass-surface mission-panel"><PanelHeader eyebrow="ACTIVE MISSION" title="Execution pulse" icon="workflow" /><div className="mission-core"><div className="progress-orb"><span>{tasks.length ? Math.round((completedTasks / tasks.length) * 100) : 0}%</span><small>complete</small></div><div><strong>{tasks.find((task) => task.status === "running")?.title ?? "Awaiting a mission"}</strong><p>{tasks.length ? "Shared task board is connected to the local backend." : "Create a task or launch a team to start coordinated work."}</p></div></div><div className="mini-steps"><span className="done" /><span className={tasks.length ? "active" : ""} /><span /><span /><span /></div><div className="mission-foot"><span><StatusBeacon state={connection === "open" ? "active" : "warning"} /> {connection === "open" ? "WebSocket synced" : "Reconnecting"}</span><span className="mono">{system?.platform ?? "local"} / {system?.arch ?? "runtime"}</span></div></div><div className="panel glass-surface task-panel"><PanelHeader eyebrow="SHARED TASK BOARD" title="Queue pressure" icon="tasks" action={<span className="panel-count">{tasks.length.toString().padStart(2, "0")}</span>} /><div className="task-columns"><TaskColumn label="READY" items={tasks.filter((task) => task.status === "queued")} /><TaskColumn label="RUNNING" items={tasks.filter((task) => task.status === "running")} /><TaskColumn label="DONE" items={tasks.filter((task) => task.status === "completed")} /></div></div><div className="panel glass-surface events-panel"><PanelHeader eyebrow="LIVE TELEMETRY" title="Event feed" icon="network" action={<span className="stream-state"><StatusBeacon state={connection === "open" ? "active" : "warning"} />{connection}</span>} /><div className="event-list">{events.length === 0 && <EmptyState icon="network" text="Listening for backend events" />}{events.slice(0, 6).map((event, index) => <div className="event-row" key={`${event.at}-${index}`}><span className="event-time">{formatTime(event.at)}</span><ThreeDIcon name={event.type.startsWith("agent") ? "agents" : event.type.startsWith("task") ? "tasks" : "network"} size="inline" state={stateFor(event.type.includes("error") ? "error" : "active")} /><code>{event.type}</code><span className="event-payload">{JSON.stringify(event.payload)}</span></div>)}</div></div></section></>; }
function Metric({ icon, label, value, detail, state }: { icon: ThreeDIconName; label: string; value: string; detail: string; state: ThreeDIconState }) { return <div className="metric-card glass-surface"><ThreeDIcon name={icon} size="module" state={state} /><div><span className="metric-label">{label}</span><strong className="metric-value">{value}</strong><span className="metric-detail">{detail}</span></div></div>; }
function PanelHeader({ eyebrow, title, icon, action }: { eyebrow: string; title: string; icon: ThreeDIconName; action?: ReactNode }) { return <div className="panel-heading"><div className="panel-heading-left"><ThreeDIcon name={icon} size="compact" state="active" /><div><p className="eyebrow">{eyebrow}</p><h3>{title}</h3></div></div>{action}</div>; }
function AgentCard({ agent }: { agent: AgentRecord }) { const metadata = parseJson<{ iconSlug?: string }>(agent.metadata_json, {}); return <article className="agent-card pressed-control"><div className="agent-card-top"><AgentBrandIcon slug={metadata.iconSlug ?? agent.id} label={agent.name} size="feature" /><span className={`pill ${statusClass(agent.status)}`}>{agent.status}</span></div><strong>{agent.name}</strong><span className="mono">{agent.executable}</span><div className="agent-card-meta"><span>{agent.version ?? "version unknown"}</span><span>{agent.kind}</span></div></article>; }
function TaskColumn({ label, items }: { label: string; items: TaskRecord[] }) { return <div className="task-column"><span className="column-label">{label}<b>{items.length}</b></span>{items.slice(0, 3).map((task) => <div className="task-chip" key={task.id}><span>{task.title}</span><small>P{task.priority}</small></div>)}{items.length === 0 && <span className="column-empty">—</span>}</div>; }
function MiniStat({ label, value }: { label: string; value: string | number }) { return <div><span className="eyebrow">{label}</span><strong>{value}</strong></div>; }
function EmptyState({ icon, text }: { icon: ThreeDIconName; text: string }) { return <div className="empty-state"><ThreeDIcon name={icon} size="feature" state="neutral" /><span>{text}</span></div>; }
function FolderIcon() { return <ThreeDIcon name="memory" size="inline" state="active" />; }
function ThemeToggle({ theme, onToggle }: { theme: ThemeName; onToggle: () => void }) { return <button className={`theme-toggle pressed-control ${theme}`} onClick={onToggle} aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} theme`}><span className="theme-track"><span className="theme-knob">{theme === "dark" ? <Moon size={13} /> : <Sun size={13} />}</span></span><span className="theme-label">{theme}</span></button>; }
function CommandPalette({ query, onQuery, onClose, onCommand }: { query: string; onQuery: (value: string) => void; onClose: () => void; onCommand: (command: string) => void }) { const actions = [{ id: "refresh", label: "Refresh telemetry", icon: "health" as ThreeDIconName, shortcut: "R" }, { id: "scan", label: "Scan local agents", icon: "agents" as ThreeDIconName, shortcut: "A" }, { id: "theme", label: "Toggle theme", icon: "system" as ThreeDIconName, shortcut: "T" }, ...navigation.filter((item) => item.id !== "overview").map((item) => ({ id: item.id, label: `Open ${item.label}`, icon: item.icon, shortcut: "" }))]; const filtered = actions.filter((action) => action.label.toLowerCase().includes(query.toLowerCase())); return <div className="palette-backdrop" onMouseDown={onClose}><div className="command-palette glass-surface" onMouseDown={(event) => event.stopPropagation()}><div className="palette-header"><Search size={17} /><input autoFocus value={query} onChange={(event) => onQuery(event.target.value)} placeholder="Search modules, actions, agents…" /><button className="icon-button" onClick={onClose} aria-label="Close command palette"><X size={16} /></button></div><div className="palette-list">{filtered.map((action) => <button key={action.id} className="palette-item" onClick={() => onCommand(action.id)}><ThreeDIcon name={action.icon} size="compact" state="active" /><span>{action.label}</span>{action.shortcut && <kbd>{action.shortcut}</kbd>}</button>)}{filtered.length === 0 && <div className="palette-empty">No matching commands</div>}</div><div className="palette-footer"><span><Command size={12} /> Navigate with Ctrl+K</span><span>Esc to close</span></div></div></div>; }
function CredentialDialog({ onClose, onSaved }: { onClose: () => void; onSaved: (providers: string[]) => void }) { const [npmToken, setNpmToken] = useState(""); const [pypiToken, setPypiToken] = useState(""); const [showNpm, setShowNpm] = useState(false); const [showPypi, setShowPypi] = useState(false); const submit = (event: FormEvent) => { event.preventDefault(); const providers = [npmToken.trim() ? "npm" : "", pypiToken.trim() ? "PyPI" : ""].filter(Boolean); if (providers.length) onSaved(providers); }; return <div className="credential-backdrop" role="presentation" onMouseDown={onClose}><section className="credential-dialog glass-surface" role="dialog" aria-modal="true" aria-labelledby="credential-dialog-title" onMouseDown={(event) => event.stopPropagation()}><div className="credential-dialog-header"><div><span className="eyebrow accent">LOCAL SESSION / REGISTRY ACCESS</span><h3 id="credential-dialog-title">Enter publishing credentials</h3><p>Use a token only when you are ready to publish. Values are held in this dialog and are never sent to the UTHARNESS backend or written to SQLite.</p></div><button className="icon-button" aria-label="Close credentials dialog" onClick={onClose}><X size={16} /></button></div><div className="credential-warning"><ShieldCheck size={18} /><span>Do not paste credentials into chat, source files, screenshots, or terminal logs. Closing or refreshing this page clears these fields.</span></div><form className="stack-form credential-form" onSubmit={submit}><FormField label="NPM access token"><div className="credential-input"><input type={showNpm ? "text" : "password"} value={npmToken} onChange={(event) => setNpmToken(event.target.value)} autoComplete="new-password" spellCheck={false} placeholder="npm_…" aria-describedby="credential-help" /><button type="button" className="credential-visibility" aria-label={showNpm ? "Hide npm token" : "Show npm token"} onClick={() => setShowNpm((visible) => !visible)}>{showNpm ? <EyeOff size={15} /> : <Eye size={15} />}</button></div></FormField><FormField label="PyPI API token"><div className="credential-input"><input type={showPypi ? "text" : "password"} value={pypiToken} onChange={(event) => setPypiToken(event.target.value)} autoComplete="new-password" spellCheck={false} placeholder="pypi-…" aria-describedby="credential-help" /><button type="button" className="credential-visibility" aria-label={showPypi ? "Hide PyPI token" : "Show PyPI token"} onClick={() => setShowPypi((visible) => !visible)}>{showPypi ? <EyeOff size={15} /> : <Eye size={15} />}</button></div></FormField><p id="credential-help" className="form-help">This popup does not publish packages by itself. NPM supports the current Node packages; PyPI remains unavailable until a Python distribution is added.</p><div className="credential-dialog-actions"><button type="button" className="secondary-button pressed-control" onClick={onClose}>Cancel</button><button type="submit" className="primary-button pressed-control" disabled={!npmToken.trim() && !pypiToken.trim()}><KeyRound size={14} /> Use for this session</button></div></form></section></div>; }

function AmbientMesh() { return <div className="ambient-mesh" aria-hidden="true"><span className="ambient-glow glow-one" /><span className="ambient-glow glow-two" /><span className="ambient-grid" /></div>; }

function ModuleView({ module, agents, tasks, events, refreshKey, onRefresh, onNotice, onError, onScan, scanning }: { module: ModuleName; agents: AgentRecord[]; tasks: TaskRecord[]; events: EventEnvelope[]; refreshKey: number; onRefresh: () => void; onNotice: (message: string) => void; onError: (cause: unknown) => void; onScan: () => void; scanning: boolean }) { const item = navigation.find((entry) => entry.id === module)!; const shared = { agents, tasks, events, refreshKey, onRefresh, onNotice, onError }; return <section className="module-view glass-surface"><div className="module-title"><ThreeDIcon name={item.icon} size="feature" state="active" /><div><span className="eyebrow accent">LIVE CONTRACT / {item.label.toUpperCase()}</span><h2>{item.label} <em>surface</em></h2><p>{item.detail} connected to the UTHARNESS backend.</p></div>{module === "agents" && <button className="primary-button pressed-control" onClick={onScan} disabled={scanning}><ThreeDIcon name="agents" size="inline" state="active" />{scanning ? "Scanning" : "Scan now"}</button>}</div>{module === "agents" && <AgentsModule {...shared} onScan={onScan} scanning={scanning} />}{module === "sessions" && <SessionsModule {...shared} />}{module === "tasks" && <TasksModule {...shared} />}{module === "teams" && <TeamsModule {...shared} />}{module === "workflows" && <WorkflowsModule {...shared} />}{module === "memory" && <MemoryModule {...shared} />}{module === "mcp" && <McpModule {...shared} />}{module === "models" && <ModelsModule {...shared} />}{module === "permissions" && <PermissionsModule {...shared} />}{module === "terminal" && <TerminalModule {...shared} />}{module === "audit" && <AuditModule {...shared} />}<div className="module-footnote"><StatusBeacon state="active" /> Durable SQLite state · live WebSocket events · localhost authority</div></section>; }
type ModuleProps = { agents: AgentRecord[]; tasks: TaskRecord[]; events: EventEnvelope[]; refreshKey: number; onRefresh: () => void; onNotice: (message: string) => void; onError: (cause: unknown) => void };
function ModuleHeader({ eyebrow, title, icon = "system", action }: { eyebrow: string; title: string; icon?: ThreeDIconName; action?: ReactNode }) { return <div className="submodule-header"><div className="submodule-title"><ThreeDIcon name={icon} size="compact" state="active" /><div><p className="eyebrow accent">{eyebrow}</p><h3>{title}</h3></div></div>{action}</div>; }
function FormField({ label, children }: { label: string; children: ReactNode }) { return <label className="form-field"><span>{label}</span>{children}</label>; }
function ModuleError({ error }: { error: string | null }) { return error ? <div className="module-inline-error">{error}</div> : null; }
function ModuleLoading({ loading }: { loading: boolean }) { return loading ? <div className="module-loading"><RefreshCw size={16} className="spin" /> Synchronizing local state…</div> : null; }
function DataTable({ children }: { children: ReactNode }) { return <div className="data-table-wrap"><table className="data-table"><tbody>{children}</tbody></table></div>; }
function TableHead({ children }: { children: ReactNode }) { return <tr className="table-head">{children}</tr>; }
function StatusPill({ status }: { status: string }) { return <span className={`pill ${statusClass(status)}`}>{status}</span>; }
function ActionButton({ children, onClick, disabled = false }: { children: ReactNode; onClick: () => void; disabled?: boolean }) { return <button className="tiny-button pressed-control" onClick={onClick} disabled={disabled}>{children}</button>; }

function AgentsModule({ events, refreshKey, onNotice, onError, onRefresh, onScan, scanning }: ModuleProps & { onScan: () => void; scanning: boolean }) {
  const [mode, setMode] = useState<"all" | AgentToolMode>("all");
  const [query, setQuery] = useState("");
  const [cwd, setCwd] = useState("/home/ubuntu/utharness-os");
  const [model, setModel] = useState("");
  const [chatInput, setChatInput] = useState("");
  const [chatSession, setChatSession] = useState<SessionRecord | null>(null);
  const [chatLines, setChatLines] = useState<Array<{ role: "you" | "system"; text: string }>>([]);
  const [selectedToolId, setSelectedToolId] = useState("");
  const [busyToolId, setBusyToolId] = useState<string | null>(null);
  const [jobId, setJobId] = useState<string | null>(null); const [installJob, setInstallJob] = useState<InstallJobRecord | null>(null); const [setupTool, setSetupTool] = useState<AgentToolRecord | null>(null);
  const load = useCallback(() => client.agentTools(mode === "all" ? { q: query } : { mode, q: query }), [mode, query]);
  const { data, loading, error, reload } = useDataLoader(load, refreshKey);
  const tools = data?.tools ?? [];
  const liveOutputLines = useMemo(() => chatSession ? events.filter((event) => event.type === "agent.output" && String(event.payload.sessionId ?? "") === chatSession.id).flatMap((event) => normalizeTerminalText(String(event.payload.data ?? "")).split(/\r?\n/)).filter(Boolean).slice(-80) : [], [chatSession, events]);
  const installOutput = useMemo(() => { if (!installJob) return ""; const live = events.filter((event) => event.type === "agent.install.output" && String(event.payload.jobId ?? "") === installJob.id).map((event) => String(event.payload.data ?? "")).join(""); return normalizeTerminalText(installJob.output || live).slice(-4000); }, [events, installJob]);
  useEffect(() => { if (data?.selectedToolId) setSelectedToolId(data.selectedToolId); }, [data?.selectedToolId]);
  useEffect(() => {
    if (!jobId) return;
    const timer = window.setInterval(() => {
      void client.agentInstallation(jobId).then(async (job) => {
        setInstallJob(job);
        if (job.status === "completed" || job.status === "failed") {
          setJobId(null); setBusyToolId(null);
          if (job.status === "completed") { onNotice("Agent tool installed and discovery refreshed"); await reload(); await onRefresh(); }
          else onError(new Error(job.error ?? "Agent installation failed"));
        }
      }).catch(onError);
    }, 1200);
    return () => window.clearInterval(timer);
  }, [jobId, onError, onRefresh, reload]);
  const install = async (tool: AgentToolRecord) => {
    setBusyToolId(tool.id);
    try { const job = await client.installAgentTool(tool.id); setInstallJob(job); setJobId(job.id); onNotice(`Installing ${tool.name} from its allowlisted package source`); }
    catch (cause) { setBusyToolId(null); onError(cause); }
  };
  const select = async (tool: AgentToolRecord) => {
    try { await client.selectAgentTool(tool.id); setSelectedToolId(tool.id); onNotice(`${tool.name} selected as the active local tool`); }
    catch (cause) { onError(cause); }
  };
  const openChat = async (tool: AgentToolRecord) => {
    if (!tool.detected) return onError(new Error(`Install or detect ${tool.name} before opening chat`));
    setBusyToolId(tool.id);
    try {
      const result = await client.openAgentChat(tool.id, cwd, model || undefined, chatInput || undefined);
      setChatSession(result.session); setChatLines(chatInput ? [{ role: "you", text: chatInput }] : []); setChatInput(""); onNotice(`${tool.name} chat session opened`);
    } catch (cause) { onError(cause); }
    finally { setBusyToolId(null); }
  };
  const sendChat = async (event: FormEvent) => {
    event.preventDefault();
    if (!chatSession || !chatInput.trim()) return;
    const message = chatInput.trim();
    try { await client.sendSessionInput(chatSession.id, `${message}\n`); setChatLines((current) => [...current, { role: "you", text: message }]); setChatInput(""); }
    catch (cause) { onError(cause); }
  };
  const closeChat = async () => { if (!chatSession) return; try { await client.stopSession(chatSession.id); setChatSession(null); onNotice("Agent chat session stopped"); await onRefresh(); } catch (cause) { onError(cause); } };
  const copySetupCommand = async () => { const command = setupTool ? setupCommand(setupTool) : null; if (!command) return; try { await navigator.clipboard.writeText(command); onNotice("Official setup command copied to clipboard"); } catch { onError(new Error("Clipboard access is unavailable; copy the command manually")); } };
  return <>
    <div className="module-stats"><MiniStat label="Catalog" value={tools.length} /><MiniStat label="Detected" value={tools.filter((tool) => tool.detected).length} /><MiniStat label="Selected" value={selectedToolId ? tools.find((tool) => tool.id === selectedToolId)?.name ?? selectedToolId : "None"} /><MiniStat label="Authority" value="LOCAL" /></div>
    <div className="agent-catalog-toolbar"><label className="search-field"><Search size={13} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search official tools…" /></label><label className="compact-select"><span>View</span><select value={mode} onChange={(event) => setMode(event.target.value as "all" | AgentToolMode)}><option value="all">All tools</option><option value="cli">Local CLI</option><option value="editor">Editors</option><option value="framework">Frameworks</option><option value="service">Services</option><option value="hosted">Hosted</option></select></label><ActionButton onClick={onScan} disabled={scanning}>{scanning ? "Scanning" : "Detect installed"}</ActionButton></div>{installJob && <div className={`notice-banner install-progress ${installJob.status === "failed" ? "install-failed" : ""}`}><RefreshCw size={14} className={installJob.status === "running" || installJob.status === "queued" ? "spin" : ""} /><div><strong>INSTALL {installJob.status.toUpperCase()}</strong><pre>{installOutput || "Waiting for installer output…"}</pre></div>{installJob.status === "running" && <ActionButton onClick={() => void client.stopAgentInstallation(installJob.id)}>Stop</ActionButton>}</div>}
    <ModuleLoading loading={loading} /><ModuleError error={error} />
    <div className="agent-catalog-grid">{tools.map((tool) => <article className={`agent-catalog-card ${selectedToolId === tool.id ? "selected" : ""}`} key={tool.id}>
      <div className="agent-catalog-card-head"><AgentBrandIcon slug={tool.iconSlug} label={tool.name} size="feature" /><div><strong>{tool.name}</strong><span>{tool.publisher}</span></div><StatusPill status={tool.detected ? "available" : tool.latestInstall?.status ?? tool.mode} /></div>
      <p>{tool.description}</p><div className="agent-capability-row">{tool.capabilities.slice(0, 4).map((capability) => <span key={capability}>{capability}</span>)}</div>
      <div className="agent-catalog-meta"><span>{tool.mode}</span><span>{tool.installer.kind === "manual" ? "official setup" : tool.installer.packageName ?? "catalog source"}</span></div>
      <div className="agent-catalog-actions"><button className="tiny-button pressed-control" onClick={() => void select(tool)}>{selectedToolId === tool.id ? "Selected" : "Select"}</button>{tool.mode === "cli" && tool.detected ? <button className="primary-button compact-primary pressed-control" onClick={() => void openChat(tool)} disabled={busyToolId === tool.id}>{busyToolId === tool.id ? "Opening…" : "Open chat"}</button> : tool.installer.kind === "npm" || tool.installer.kind === "python" ? <button className="primary-button compact-primary pressed-control" onClick={() => void install(tool)} disabled={busyToolId === tool.id}>{busyToolId === tool.id ? "Installing…" : "Install"}</button> : <button className="primary-button compact-primary pressed-control" onClick={() => setSetupTool(tool)}>Setup guide</button>}<a className="catalog-source-link" href={tool.repositoryUrl ?? tool.officialUrl} target="_blank" rel="noreferrer">Source <ChevronRight size={12} /></a></div>
    </article>)}</div>
    <div className="surface-grid lower-grid"><div className="subsurface"><ModuleHeader eyebrow="SELECTED RUNTIME" title="Chat setup" icon="terminal" />{selectedToolId ? <form className="stack-form" onSubmit={(event) => { event.preventDefault(); const tool = tools.find((item) => item.id === selectedToolId); if (tool) void openChat(tool); }}><FormField label="Working directory"><input value={cwd} onChange={(event) => setCwd(event.target.value)} required /></FormField><FormField label="Assigned model"><input value={model} onChange={(event) => setModel(event.target.value)} placeholder="provider/model (optional)" /></FormField><FormField label="First message (optional)"><textarea value={chatInput} onChange={(event) => setChatInput(event.target.value)} rows={4} placeholder="Ask the selected local agent to inspect the workspace…" /></FormField><button className="primary-button pressed-control" disabled={busyToolId !== null || !tools.some((tool) => tool.id === selectedToolId && tool.detected)}>{busyToolId ? "Working…" : "Open selected chat"}</button></form> : <p className="muted-copy">Select a catalog entry to configure its workspace, model, and first message.</p>}</div><div className="subsurface terminal-surface"><ModuleHeader eyebrow="LIVE AGENT CHAT" title={chatSession ? `Session ${chatSession.id.slice(0, 8)}` : "No active chat"} action={chatSession ? <ActionButton onClick={() => void closeChat()}>Stop</ActionButton> : undefined} /><div className="terminal-output agent-chat-output">{chatLines.map((line, index) => <div key={`${line.role}-${index}`}><strong>{line.role === "you" ? "YOU" : "SYSTEM"}</strong> {line.text}</div>)}{liveOutputLines.map((line, index) => <div key={`agent-output-${index}`}><strong>AGENT</strong> {line}</div>)}{!chatLines.length && !liveOutputLines.length && <span className="muted-copy">Open a detected CLI agent to stream terminal chat here.</span>}</div>{chatSession && <form className="inline-form terminal-input" onSubmit={(event) => void sendChat(event)}><input value={chatInput} onChange={(event) => setChatInput(event.target.value)} placeholder="Send a message to the active agent…" /><button className="tiny-button pressed-control">Send</button></form>}</div></div>{setupTool && <div className="setup-backdrop" role="presentation" onMouseDown={() => setSetupTool(null)}><section className="setup-dialog glass-surface" role="dialog" aria-modal="true" aria-labelledby="setup-dialog-title" onMouseDown={(event) => event.stopPropagation()}><div className="setup-dialog-header"><div><span className="eyebrow accent">OFFICIAL SETUP / {setupTool.mode.toUpperCase()}</span><h3 id="setup-dialog-title">{setupTool.name}</h3><p>{setupTool.description}</p></div><button className="icon-button" aria-label="Close setup guide" onClick={() => setSetupTool(null)}><X size={16} /></button></div><div className="setup-dialog-grid"><div><span className="field-caption">Publisher</span><strong>{setupTool.publisher}</strong></div><div><span className="field-caption">Capabilities</span><strong>{setupTool.capabilities.join(" · ")}</strong></div><div><span className="field-caption">Installer</span><strong>{setupTool.installer.kind === "manual" ? "Official instructions" : setupTool.installer.kind.toUpperCase()}</strong></div></div>{setupTool.installer.note && <p className="setup-note">{setupTool.installer.note}</p>}{setupCommand(setupTool) && <div className="setup-command"><span className="field-caption">Allowlisted local command</span><code>{setupCommand(setupTool)}</code><button className="tiny-button pressed-control" onClick={() => void copySetupCommand()}>Copy command</button></div>}<div className="setup-dialog-actions"><a className="secondary-button pressed-control" href={setupTool.officialUrl} target="_blank" rel="noreferrer">Official site <ChevronRight size={13} /></a>{setupTool.docsUrl && <a className="secondary-button pressed-control" href={setupTool.docsUrl} target="_blank" rel="noreferrer">Documentation <ChevronRight size={13} /></a>}{(setupTool.repositoryUrl ?? setupTool.officialUrl) && <a className="text-button" href={setupTool.repositoryUrl ?? setupTool.officialUrl} target="_blank" rel="noreferrer">View source <ChevronRight size={13} /></a>}</div></section></div>}
  </>;
}

function SessionsModule({ refreshKey, onNotice, onError, onRefresh }: ModuleProps) { const load = useCallback(() => client.sessions(), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const sessions = data?.sessions ?? []; const stop = async (id: string) => { try { await client.stopSession(id); onNotice("Session stop requested"); await reload(); await onRefresh(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Live rows" value={sessions.filter((session) => session.status === "running").length} /><MiniStat label="History" value={sessions.length} /><MiniStat label="Authority" value="SESSION MANAGER" /></div><ModuleLoading loading={loading} /><ModuleError error={error} />{sessions.length ? <DataTable><TableHead><th>PID</th><th>Agent</th><th>Status</th><th>Working directory</th><th>Model</th><th>Started</th><th /></TableHead>{sessions.map((session) => <tr key={session.id}><td className="mono">{session.pid ?? "—"}</td><td className="mono">{session.agent_id}</td><td><StatusPill status={session.status} /></td><td className="mono truncate-cell">{session.cwd}</td><td>{session.assigned_model ?? "default"}</td><td>{formatDate(session.started_at)}</td><td>{session.status === "running" && <ActionButton onClick={() => void stop(session.id)}>Stop</ActionButton>}</td></tr>)}</DataTable> : !loading && <EmptyState icon="sessions" text="No persisted sessions. Launch one from Agents or the CLI." />}</>; }

function TasksModule({ tasks: initialTasks, refreshKey, onNotice, onError, onRefresh }: ModuleProps) { const load = useCallback(() => client.tasks(), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const tasks = data?.tasks ?? initialTasks; const [filter, setFilter] = useState("all"); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [priority, setPriority] = useState("5"); const visible = filter === "all" ? tasks : tasks.filter((task) => task.status === filter); const submit = async (event: FormEvent) => { event.preventDefault(); try { await client.createTask(title, description, Number(priority)); setTitle(""); setDescription(""); onNotice("Task added to the shared queue"); await reload(); await onRefresh(); } catch (cause) { onError(cause); } }; const transition = async (task: TaskRecord) => { const next: Record<string, string> = { queued: "running", running: "completed", failed: "queued" }; try { await client.updateTask(task.id, next[task.status] ?? "queued"); onNotice(`${task.title} moved to ${next[task.status] ?? "queued"}`); await reload(); await onRefresh(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Visible" value={visible.length} /><MiniStat label="Completed" value={tasks.filter((task) => task.status === "completed").length} /><MiniStat label="Queue" value={tasks.filter((task) => task.status === "queued").length} /></div><div className="toolbar-row"><label className="compact-select">Filter<select value={filter} onChange={(event) => setFilter(event.target.value)}><option value="all">All statuses</option><option value="queued">Queued</option><option value="running">Running</option><option value="completed">Completed</option><option value="failed">Failed</option><option value="cancelled">Cancelled</option></select></label><span className="toolbar-meta">{visible.length} of {tasks.length} tasks</span></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface"><ModuleHeader eyebrow="KANBAN QUEUE" title="Shared task board" />{visible.length ? <DataTable><TableHead><th>Task</th><th>Status</th><th>Priority</th><th>Updated</th><th /></TableHead>{visible.map((task) => <tr key={task.id}><td><strong>{task.title}</strong><small>{task.description || "No description"}</small></td><td><StatusPill status={task.status} /></td><td className="mono">P{task.priority}</td><td>{formatDate(task.updated_at)}</td><td>{task.status !== "completed" && task.status !== "cancelled" && <ActionButton onClick={() => void transition(task)}>{task.status === "failed" ? "Retry" : task.status === "queued" ? "Run" : "Complete"}</ActionButton>}</td></tr>)}</DataTable> : !loading && <EmptyState icon="tasks" text="No tasks match this filter." />}</div><div className="subsurface"><ModuleHeader eyebrow="NEW WORK ITEM" title="Create task" /><form className="stack-form" onSubmit={(event) => void submit(event)}><FormField label="Title"><input value={title} onChange={(event) => setTitle(event.target.value)} required maxLength={256} /></FormField><FormField label="Description"><textarea value={description} onChange={(event) => setDescription(event.target.value)} rows={4} /></FormField><FormField label="Priority"><input type="number" value={priority} onChange={(event) => setPriority(event.target.value)} min={-100} max={100} /></FormField><button className="primary-button pressed-control">Add to queue</button></form></div></div></>; }

function TeamsModule({ agents, refreshKey, onNotice, onError, onRefresh }: ModuleProps) { const load = useCallback(() => Promise.all([client.teams(), client.teamMembers(), client.teamMessages()]), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const teams = data?.[0].teams ?? []; const members = data?.[1].members ?? []; const messages = data?.[2].messages ?? []; const [name, setName] = useState(""); const [goal, setGoal] = useState(""); const [selected, setSelected] = useState<string[]>([]); const [selectedTeam, setSelectedTeam] = useState(""); const [message, setMessage] = useState(""); const teamId = selectedTeam || teams[0]?.id || ""; const submit = async (event: FormEvent) => { event.preventDefault(); try { await client.createTeam(name, goal, selected); setName(""); setGoal(""); setSelected([]); onNotice("Agent council created"); await reload(); await onRefresh(); } catch (cause) { onError(cause); } }; const run = async (id: string) => { try { await client.runTeam(id); onNotice("Team run completed"); await reload(); await onRefresh(); } catch (cause) { onError(cause); } }; const send = async (event: FormEvent) => { event.preventDefault(); if (!teamId) return onError(new Error("Select a team first")); try { await client.sendTeamMessage(teamId, "local-user", message); setMessage(""); onNotice("Mailbox message sent"); await reload(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Councils" value={teams.length} /><MiniStat label="Members" value={members.length} /><MiniStat label="Mailbox" value={messages.length} /></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface"><ModuleHeader eyebrow="COORDINATION" title="Agent councils" />{teams.length ? <div className="record-list">{teams.map((team) => <article className={`record-card ${team.id === teamId ? "selected" : ""}`} key={team.id}><button className="record-card-main" onClick={() => setSelectedTeam(team.id)}><div><strong>{team.name}</strong><p>{team.goal}</p></div><small>{members.filter((member) => member.team_id === team.id).length} assigned members · {formatDate(team.created_at)}</small></button><div className="record-card-actions"><StatusPill status={team.status} /><ActionButton onClick={() => void run(team.id)}>Run</ActionButton></div></article>)}</div> : !loading && <EmptyState icon="teams" text="Create a council to coordinate local agents." />}</div><div className="subsurface"><ModuleHeader eyebrow="NEW COUNCIL" title="Create team" /><form className="stack-form" onSubmit={(event) => void submit(event)}><FormField label="Name"><input value={name} onChange={(event) => setName(event.target.value)} required /></FormField><FormField label="Goal"><textarea value={goal} onChange={(event) => setGoal(event.target.value)} rows={3} required /></FormField><span className="field-caption">Assign agents</span><div className="check-grid">{agents.map((agent) => <label key={agent.id}><input type="checkbox" checked={selected.includes(agent.id)} onChange={() => setSelected((current) => current.includes(agent.id) ? current.filter((id) => id !== agent.id) : [...current, agent.id])} />{agent.name}</label>)}</div><button className="primary-button pressed-control">Create council</button></form></div></div><div className="surface-grid lower-grid"><div className="subsurface"><ModuleHeader eyebrow="MAILBOX" title={teamId ? "Team messages" : "Select a team"} />{teamId && <form className="inline-form" onSubmit={(event) => void send(event)}><input value={message} onChange={(event) => setMessage(event.target.value)} placeholder="Send a coordination note…" required /><button className="tiny-button pressed-control">Send</button></form>}<div className="message-list">{messages.filter((item) => !teamId || item.team_id === teamId).map((item) => <article className="message-card" key={item.id}><div><strong>{item.sender}</strong><small>{formatDate(item.created_at)}</small></div><p>{item.content}</p></article>)}{messages.filter((item) => !teamId || item.team_id === teamId).length === 0 && <span className="muted-copy">No mailbox messages for this council.</span>}</div></div><div className="subsurface"><ModuleHeader eyebrow="MEMBERS" title="Assignments" /><div className="member-list">{members.filter((member) => !teamId || member.team_id === teamId).map((member) => <div className="member-row" key={`${member.team_id}-${member.agent_id}`}><ThreeDIcon name="agents" size="inline" state="active" /><span className="mono">{member.agent_id}</span><StatusPill status={member.role} /></div>)}{members.filter((member) => !teamId || member.team_id === teamId).length === 0 && <span className="muted-copy">No members assigned.</span>}</div></div></div></>; }

function WorkflowsModule({ tasks, refreshKey, onNotice, onError, onRefresh }: ModuleProps) { const load = useCallback(() => Promise.all([client.workflows(), client.workflowRuns()]), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const workflows = data?.[0].workflows ?? []; const runs = data?.[1].runs ?? []; const [name, setName] = useState(""); const [selectedTasks, setSelectedTasks] = useState<string[]>([]); const submit = async (event: FormEvent) => { event.preventDefault(); try { const steps = selectedTasks.map((taskId, index) => ({ id: `step-${index + 1}`, taskId, ...(index > 0 ? { dependsOn: [`step-${index}`] } : {}) })); await client.createWorkflow(name, steps.length ? steps : [{ id: "manual" }]); setName(""); setSelectedTasks([]); onNotice("Workflow definition saved"); await reload(); await onRefresh(); } catch (cause) { onError(cause); } }; const run = async (id: string) => { try { await client.runWorkflow(id); onNotice("Workflow run completed"); await reload(); await onRefresh(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Definitions" value={workflows.length} /><MiniStat label="Runs" value={runs.length} /><MiniStat label="Completed" value={runs.filter((run) => run.status === "completed").length} /></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface"><ModuleHeader eyebrow="EXECUTION GRAPHS" title="Workflow definitions" />{workflows.length ? <div className="record-list">{workflows.map((workflow) => { const definition = parseJson<{ steps?: Array<{ id: string; taskId?: string; dependsOn?: string[] }> }>(workflow.definition_json, {}); const lastRun = runs.find((item) => item.workflow_id === workflow.id); return <article className="record-card" key={workflow.id}><div><strong>{workflow.name}</strong><p>{definition.steps?.length ?? 0} steps · {lastRun ? `last run ${lastRun.status}` : "never run"}</p></div><div className="record-card-actions"><StatusPill status={lastRun?.status ?? "queued"} /><ActionButton onClick={() => void run(workflow.id)}>Run</ActionButton></div><small className="mono">{definition.steps?.map((step) => step.id).join(" → ") || "manual"}</small></article>; })}</div> : !loading && <EmptyState icon="workflows" text="Create a workflow from queued tasks." />}</div><div className="subsurface"><ModuleHeader eyebrow="NEW GRAPH" title="Compose workflow" /><form className="stack-form" onSubmit={(event) => void submit(event)}><FormField label="Workflow name"><input value={name} onChange={(event) => setName(event.target.value)} required /></FormField><span className="field-caption">Ordered task steps</span><div className="check-grid">{tasks.filter((task) => task.status !== "completed").slice(0, 8).map((task) => <label key={task.id}><input type="checkbox" checked={selectedTasks.includes(task.id)} onChange={() => setSelectedTasks((current) => current.includes(task.id) ? current.filter((id) => id !== task.id) : [...current, task.id])} />{task.title}</label>)}</div><button className="primary-button pressed-control">Save workflow</button></form></div></div><div className="subsurface"><ModuleHeader eyebrow="RUN HISTORY" title="Recent workflow runs" />{runs.length ? <DataTable><TableHead><th>Status</th><th>Workflow</th><th>Started</th><th>Ended</th></TableHead>{runs.map((run) => <tr key={run.id}><td><StatusPill status={run.status} /></td><td className="mono">{run.workflow_id}</td><td>{formatDate(run.started_at)}</td><td>{formatDate(run.ended_at)}</td></tr>)}</DataTable> : <span className="muted-copy">No workflow runs yet.</span>}</div></>; }

function MemoryModule({ refreshKey, onNotice, onError }: ModuleProps) { const load = useCallback(() => client.memory(), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const memory = data?.memory ?? []; const [scope, setScope] = useState("workspace"); const [key, setKey] = useState(""); const [value, setValue] = useState(""); const submit = async (event: FormEvent) => { event.preventDefault(); try { await client.saveMemory(scope, key, value); setKey(""); setValue(""); onNotice("Memory entry persisted locally"); await reload(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Entries" value={memory.length} /><MiniStat label="Scopes" value={new Set(memory.map((item) => item.scope)).size} /><MiniStat label="Authority" value="SQLITE" /></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface"><ModuleHeader eyebrow="LOCAL CONTEXT" title="Key-value memory" />{memory.length ? <DataTable><TableHead><th>Scope</th><th>Key</th><th>Value</th><th>Updated</th></TableHead>{memory.map((item) => <tr key={item.id}><td><StatusPill status={item.scope} /></td><td className="mono">{item.key}</td><td className="truncate-cell">{item.value}</td><td>{formatDate(item.updated_at)}</td></tr>)}</DataTable> : !loading && <EmptyState icon="memory" text="No local memory entries yet." />}</div><div className="subsurface"><ModuleHeader eyebrow="WRITE CONTEXT" title="Save entry" /><form className="stack-form" onSubmit={(event) => void submit(event)}><FormField label="Scope"><input value={scope} onChange={(event) => setScope(event.target.value)} required /></FormField><FormField label="Key"><input value={key} onChange={(event) => setKey(event.target.value)} required /></FormField><FormField label="Value"><textarea value={value} onChange={(event) => setValue(event.target.value)} rows={5} required /></FormField><button className="primary-button pressed-control">Persist memory</button></form></div></div></>; }

function McpModule({ refreshKey, onNotice, onError }: ModuleProps) { const load = useCallback(() => client.mcp(), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const servers = data?.mcp ?? []; const [name, setName] = useState(""); const [transport, setTransport] = useState("stdio"); const [endpoint, setEndpoint] = useState(""); const [command, setCommand] = useState(""); const submit = async (event: FormEvent) => { event.preventDefault(); try { await client.createMcp(name, transport, endpoint || undefined, command || undefined); setName(""); setEndpoint(""); setCommand(""); onNotice("MCP server registered"); await reload(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Servers" value={servers.length} /><MiniStat label="Enabled" value={servers.filter((server) => server.enabled).length} /><MiniStat label="Transport" value={new Set(servers.map((server) => server.transport)).size || 0} /></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface"><ModuleHeader eyebrow="TOOL CONTROL" title="Registered MCP servers" />{servers.length ? <DataTable><TableHead><th>Name</th><th>Transport</th><th>Endpoint / command</th><th>Status</th></TableHead>{servers.map((server) => <tr key={server.id}><td><strong>{server.name}</strong><small>{server.id}</small></td><td><StatusPill status={server.transport} /></td><td className="mono truncate-cell">{server.endpoint ?? server.command ?? "—"}</td><td><StatusPill status={server.enabled ? "enabled" : "disabled"} /></td></tr>)}</DataTable> : !loading && <EmptyState icon="mcp" text="No MCP servers registered." />}</div><div className="subsurface"><ModuleHeader eyebrow="REGISTRATION" title="Add MCP server" /><form className="stack-form" onSubmit={(event) => void submit(event)}><FormField label="Name"><input value={name} onChange={(event) => setName(event.target.value)} required /></FormField><FormField label="Transport"><select value={transport} onChange={(event) => setTransport(event.target.value)}><option value="stdio">stdio</option><option value="sse">sse</option><option value="http">http</option></select></FormField><FormField label="Endpoint (for SSE / HTTP)"><input value={endpoint} onChange={(event) => setEndpoint(event.target.value)} placeholder="http://127.0.0.1:9000" /></FormField><FormField label="Command (for stdio)"><input value={command} onChange={(event) => setCommand(event.target.value)} placeholder="npx server-command" /></FormField><button className="primary-button pressed-control">Register server</button></form></div></div></>; }

function ModelsModule({ refreshKey, onNotice, onError }: ModuleProps) { const load = useCallback(() => Promise.all([client.models(), client.providers()]), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const models = data?.[0].models ?? []; const providers = data?.[1].providers ?? []; const [providerName, setProviderName] = useState(""); const [providerKind, setProviderKind] = useState("local"); const [providerEndpoint, setProviderEndpoint] = useState(""); const [modelName, setModelName] = useState(""); const [modelId, setModelId] = useState(""); const addProvider = async (event: FormEvent) => { event.preventDefault(); try { await client.createProvider(providerName, providerKind, providerEndpoint || undefined); setProviderName(""); setProviderEndpoint(""); onNotice("Provider registered"); await reload(); } catch (cause) { onError(cause); } }; const addModel = async (event: FormEvent) => { event.preventDefault(); try { await client.createModel(modelName, modelId, providers[0]?.id); setModelName(""); setModelId(""); onNotice("Model registered"); await reload(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Models" value={models.length} /><MiniStat label="Providers" value={providers.length} /><MiniStat label="Enabled" value={providers.filter((provider) => provider.enabled).length} /></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface"><ModuleHeader eyebrow="PROVIDER HUB" title="Providers" />{providers.length ? <DataTable><TableHead><th>Provider</th><th>Kind</th><th>Endpoint</th><th>Status</th></TableHead>{providers.map((provider) => <tr key={provider.id}><td><strong>{provider.name}</strong><small>{provider.id}</small></td><td>{provider.kind}</td><td className="mono truncate-cell">{provider.endpoint ?? "local"}</td><td><StatusPill status={provider.enabled ? "enabled" : "disabled"} /></td></tr>)}</DataTable> : !loading && <EmptyState icon="models" text="No model providers registered." />}<form className="stack-form compact-form" onSubmit={(event) => void addProvider(event)}><span className="field-caption">Register provider</span><FormField label="Name"><input value={providerName} onChange={(event) => setProviderName(event.target.value)} required /></FormField><FormField label="Kind"><input value={providerKind} onChange={(event) => setProviderKind(event.target.value)} required /></FormField><FormField label="Endpoint"><input value={providerEndpoint} onChange={(event) => setProviderEndpoint(event.target.value)} placeholder="http://127.0.0.1:8000" /></FormField><button className="tiny-button pressed-control">Add provider</button></form></div><div className="subsurface"><ModuleHeader eyebrow="MODEL CATALOG" title="Registered models" />{models.length ? <DataTable><TableHead><th>Display name</th><th>Model</th><th>Provider</th></TableHead>{models.map((model) => <tr key={model.id}><td><strong>{model.name}</strong></td><td className="mono">{model.model_name}</td><td>{model.provider_id ?? "unbound"}</td></tr>)}</DataTable> : !loading && <EmptyState icon="models" text="No model definitions registered." />}<form className="stack-form compact-form" onSubmit={(event) => void addModel(event)}><span className="field-caption">Register model</span><FormField label="Display name"><input value={modelName} onChange={(event) => setModelName(event.target.value)} required /></FormField><FormField label="Model identifier"><input value={modelId} onChange={(event) => setModelId(event.target.value)} placeholder="llama3.1:8b" required /></FormField><button className="tiny-button pressed-control">Add model</button></form></div></div></>; }

function PermissionsModule({ refreshKey, onNotice, onError }: ModuleProps) { const load = useCallback(() => Promise.all([client.permissions(), client.approvals()]), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const permissions = data?.[0].permissions ?? []; const approvals = data?.[1].approvals ?? []; const [subject, setSubject] = useState("local-user"); const [action, setAction] = useState("session.create"); const [resource, setResource] = useState("agent:*"); const [effect, setEffect] = useState("allow"); const [approvalResource, setApprovalResource] = useState(""); const addPermission = async (event: FormEvent) => { event.preventDefault(); try { await client.createPermission(subject, action, resource, effect); onNotice("Permission rule stored"); await reload(); } catch (cause) { onError(cause); } }; const addApproval = async (event: FormEvent) => { event.preventDefault(); try { await client.createApproval(subject, action, approvalResource); setApprovalResource(""); onNotice("Approval request queued"); await reload(); } catch (cause) { onError(cause); } }; const resolve = async (approval: ApprovalRecord, status: "approved" | "denied") => { try { await client.resolveApproval(approval.id, status); onNotice(`Approval ${status}`); await reload(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Rules" value={permissions.length} /><MiniStat label="Pending" value={approvals.filter((approval) => approval.status === "pending").length} /><MiniStat label="Authority" value="LOCAL USER" /></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface"><ModuleHeader eyebrow="APPROVAL QUEUE" title="Pending decisions" />{approvals.length ? <DataTable><TableHead><th>Subject</th><th>Action</th><th>Resource</th><th>Status</th><th /></TableHead>{approvals.map((approval) => <tr key={approval.id}><td>{approval.subject}</td><td className="mono">{approval.action}</td><td className="mono truncate-cell">{approval.resource}</td><td><StatusPill status={approval.status} /></td><td>{approval.status === "pending" && <span className="button-pair"><ActionButton onClick={() => void resolve(approval, "approved")}>Allow</ActionButton><ActionButton onClick={() => void resolve(approval, "denied")}>Deny</ActionButton></span>}</td></tr>)}</DataTable> : !loading && <EmptyState icon="permissions" text="No approval requests are waiting." />}<form className="stack-form compact-form" onSubmit={(event) => void addApproval(event)}><span className="field-caption">Request access</span><FormField label="Resource"><input value={approvalResource} onChange={(event) => setApprovalResource(event.target.value)} placeholder="terminal:/home/ubuntu" required /></FormField><button className="tiny-button pressed-control">Queue approval</button></form></div><div className="subsurface"><ModuleHeader eyebrow="POLICY ENGINE" title="Permission rules" />{permissions.length ? <DataTable><TableHead><th>Subject</th><th>Action</th><th>Resource</th><th>Effect</th></TableHead>{permissions.map((permission) => <tr key={permission.id}><td>{permission.subject}</td><td className="mono">{permission.action}</td><td className="mono truncate-cell">{permission.resource}</td><td><StatusPill status={permission.effect} /></td></tr>)}</DataTable> : !loading && <EmptyState icon="permissions" text="No explicit permission rules stored." />}<form className="stack-form compact-form" onSubmit={(event) => void addPermission(event)}><span className="field-caption">Add rule</span><FormField label="Subject"><input value={subject} onChange={(event) => setSubject(event.target.value)} required /></FormField><FormField label="Action"><input value={action} onChange={(event) => setAction(event.target.value)} required /></FormField><FormField label="Resource"><input value={resource} onChange={(event) => setResource(event.target.value)} required /></FormField><FormField label="Effect"><select value={effect} onChange={(event) => setEffect(event.target.value)}><option value="allow">allow</option><option value="deny">deny</option></select></FormField><button className="tiny-button pressed-control">Store rule</button></form></div></div></>; }

function TerminalModule({ events, refreshKey, onNotice, onError }: ModuleProps) { const load = useCallback(() => client.terminal(), []); const { data, loading, error, reload } = useDataLoader(load, refreshKey); const terminals = data?.terminal ?? []; const [cwd, setCwd] = useState("/home/ubuntu/utharness-os"); const [selected, setSelected] = useState(""); const [input, setInput] = useState(""); const output = events.filter((event) => event.type === "terminal.output" && (!selected || String(event.payload.terminalId ?? event.payload.terminal_id ?? "") === selected)).slice(0, 12); const open = async (event: FormEvent) => { event.preventDefault(); try { const terminal = await client.openTerminal(cwd); setSelected(terminal.id); onNotice("Terminal session opened"); await reload(); } catch (cause) { onError(cause); } }; const send = async (event: FormEvent) => { event.preventDefault(); if (!selected) return onError(new Error("Open or select a terminal first")); try { await client.sendTerminalInput(selected, `${input}\n`); setInput(""); } catch (cause) { onError(cause); } }; const close = async () => { if (!selected) return; try { await client.closeTerminal(selected); onNotice("Terminal close requested"); await reload(); } catch (cause) { onError(cause); } }; return <><div className="module-stats"><MiniStat label="Sessions" value={terminals.length} /><MiniStat label="Running" value={terminals.filter((terminal) => terminal.status === "running").length} /><MiniStat label="Stream events" value={output.length} /></div><ModuleLoading loading={loading} /><ModuleError error={error} /><div className="surface-grid"><div className="subsurface terminal-surface"><ModuleHeader eyebrow="PTY SESSIONS" title="Embedded local terminal" action={selected && <ActionButton onClick={() => void close()}>Close</ActionButton>} /><div className="terminal-output" role="log" aria-live="polite">{output.length ? output.map((event, index) => <div key={`${event.at}-${index}`}>{normalizeTerminalText(String(event.payload.data ?? event.payload.output ?? JSON.stringify(event.payload)))}</div>) : <span className="muted-copy">Open a terminal and its `terminal.output` events will stream here.</span>}</div><form className="inline-form terminal-input" onSubmit={(event) => void send(event)}><input value={input} onChange={(event) => setInput(event.target.value)} placeholder={selected ? "Type a command…" : "Open a terminal first"} disabled={!selected} /><button className="tiny-button pressed-control" disabled={!selected}>Send</button></form></div><div className="subsurface"><ModuleHeader eyebrow="OPEN SESSION" title="Terminal controls" /><form className="stack-form" onSubmit={(event) => void open(event)}><FormField label="Working directory"><input value={cwd} onChange={(event) => setCwd(event.target.value)} required /></FormField><button className="primary-button pressed-control">Open PTY session</button></form><div className="record-list terminal-list">{terminals.map((terminal) => <button className={`record-card ${terminal.id === selected ? "selected" : ""}`} key={terminal.id} onClick={() => setSelected(terminal.id)}><div><strong>{terminal.shell}</strong><p className="mono">{terminal.cwd}</p></div><StatusPill status={terminal.status} /><small>{formatDate(terminal.created_at)}</small></button>)}</div></div></div></>; }

function AuditModule({ refreshKey }: ModuleProps) { const load = useCallback(() => client.audit(), []); const { data, loading, error } = useDataLoader(load, refreshKey); const audit = data?.audit ?? []; const [query, setQuery] = useState(""); const filtered = audit.filter((row) => `${row.actor} ${row.action} ${row.resource} ${row.outcome}`.toLowerCase().includes(query.toLowerCase())); return <><div className="module-stats"><MiniStat label="Events" value={audit.length} /><MiniStat label="Visible" value={filtered.length} /><MiniStat label="Authority" value="AUDIT LOG" /></div><div className="toolbar-row"><label className="search-field"><Search size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filter actor, action, resource…" /></label><span className="toolbar-meta">Latest first</span></div><ModuleLoading loading={loading} /><ModuleError error={error} />{filtered.length ? <DataTable><TableHead><th>Time</th><th>Actor</th><th>Action</th><th>Resource</th><th>Outcome</th><th>Metadata</th></TableHead>{filtered.map((row) => <tr key={row.id}><td>{formatDate(row.created_at)}</td><td>{row.actor}</td><td className="mono">{row.action}</td><td className="mono truncate-cell">{row.resource}</td><td><StatusPill status={row.outcome} /></td><td className="mono truncate-cell">{row.metadata_json}</td></tr>)}</DataTable> : !loading && <EmptyState icon="audit" text={query ? "No audit events match the filter." : "No audit events have been recorded."} />}</>; }
